use semio_framework_test_fixtures::fixture_text;
use super::*;
use crate::retained_clone::{RetainedCloneSource,RetainedCloneStep};
pub(super) fn grant(d:RetirementDemand)->RetainedCloneGrant{wallet::grant(d)}
pub(super) fn observe<T>(op:impl FnOnce()->T)->(T,(usize,usize)){crate::value::observe_retirement_allocations(op)}
pub(super) fn original<T:RetireOwned+Sync+'static>(value:T)->RetainedCloneSource<T>{wallet::admit(value)}
pub(super) fn close_source<T:RetireOwned+Sync+'static>(s:&mut RetainedCloneSource<T>){let mut turns=0;let mut idle=0;while !s.terminal_is_empty(){let d=s.next_close_demand(4096).unwrap();let g=grant(d);assert_eq!(s.next_close_demand(g.maximum_copy_bytes).unwrap(),d,"persistent source close must execute its selected event");let step=wallet::paid(crate::effect::settle(g,|effect|wallet::poll(effect,|effect,reply|s.close_into(effect.grant().maximum_copy_bytes,effect,reply)))).result.unwrap();assert!(step.progress().fits(g));if step.progress()==Default::default()&&!s.terminal_is_empty()&&s.next_close_demand(4096).unwrap()==d{idle+=1;assert!(idle<8,"persistent source closure repeats an inert exact quote: {g:?}");}else{idle=0;}turns+=1;assert!(turns<1000000);}}
pub(super) fn row(value:i64)->SealedShared<i64>{let g=wallet::cap(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:size_of::<i64>()*2,maximum_capacity_bytes:SealedShared::<i64>::birth_bytes(),maximum_release_bytes:0,maximum_depth:1});match wallet::paid(crate::admit_funded(value,SharedIssuer::owned(),g)).result{Ok((r,_))=>r,Err((e,_))=>panic!("{e}")}}
pub(super) fn list(count:usize)->PersistentList<i64>{let mut level=Vec::new();for start in(0..count).step_by(PERSISTENT_PAGE_FANOUT){let len=(count-start).min(PERSISTENT_PAGE_FANOUT);let rows=std::array::from_fn(|index|if index<len{Some(row(((start+index)*2)as i64))}else{None});match wallet::paid(crate::effect::settle(grant(PersistentList::<i64>::page_birth_demand()),|effect|PersistentList::admit_leaf(rows,len,effect))).result{Ok((page,_))=>level.push(page),Err((e,_))=>panic!("{e}")}}while level.len()>1{let mut next=Vec::new();let mut nodes=level.into_iter();loop{let children=std::array::from_fn(|_|nodes.next());if children[0].is_none(){break;}match wallet::paid(crate::effect::settle(grant(PersistentList::<i64>::page_birth_demand()),|effect|PersistentList::admit_branch(children,effect))).result{Ok((page,_))=>next.push(page),Err((e,_))=>panic!("{e}")}}level=next;}level.pop().unwrap()}
fn close(plan:&mut PersistentSet<i64>){wallet::begin_close(plan.begin_close_demand(),|effect|plan.begin_close_paid(effect));let mut turns=0;while !plan.terminal_is_empty(){let g=grant(plan.close_demand(4096).unwrap());let(s,h)=observe(||wallet::paid(crate::effect::settle(g,|effect|wallet::poll(effect,|effect,reply|plan.close_into(effect.grant().maximum_copy_bytes,effect,reply)))).result.unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));assert!(turns<50||s.progress()!=Default::default(),"persistent plan closure repeats inert quote: {g:?}");turns+=1;assert!(turns<10000,"immutable page cancellation stalled: {g:?}");}}
