#[test]fn persistent_test_wallet_uses_finite_declared_case_authority_and_true_owner_outcomes(){let scope=wallet::case(1);let before=wallet::remaining();let g=wallet::grant(RetirementDemand{capacity_bytes:SealedShared::<i64>::birth_bytes(),depth:1,..Default::default()});let(turn,heap)=observe(||wallet::paid(crate::admit_funded(7i64,SharedIssuer::owned(),g)));let work=turn.work;let(value,p)=turn.result.map_err(|(e,_)|e).unwrap();assert_eq!(work,u128::from(crate::shared_issuance::SealedShared::<i64>::birth_work_demand()));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));let after=wallet::remaining();assert_eq!(before.maximum_items-after.maximum_items,p.copied_items);assert_eq!(before.maximum_capacity_bytes-after.maximum_capacity_bytes,p.retained_capacity_bytes);assert_eq!(before.maximum_copy_bytes-after.maximum_copy_bytes,p.copied_bytes);let mut owner=crate::retirement::controlled::ControlledRetirement::new(value).map_err(|(e,_)|e).unwrap();for _ in 0..100000{if owner.terminal_is_empty(){break}let g=wallet::grant(owner.next_demand(4096).unwrap());wallet::controlled(&mut owner,g).result.unwrap();}assert!(owner.terminal_is_empty());drop(owner);drop(scope);let scope=wallet::case(65536);let row:serde_json::Value=serde_json::from_str(include_str!("🎟️wallet/📐️.json")).unwrap();assert_eq!(serde_json::json!(wallet::remaining().maximum_items),row["large"]["maximumItems"]);drop(scope);}

#[path="reply.rs"] pub(crate) mod reply;
pub(crate) mod wallet{
 use crate::{RetainedWorkOutcome,ValueError,RetirementDemand,retained_clone::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep},retirement::{RetireOwned,controlled::ControlledRetirement}};
 use std::cell::RefCell;
 struct Bank{remaining:RetainedCloneGrant,fuel:u64}
 thread_local!{static BANKS:RefCell<Vec<Bank>>=const{RefCell::new(Vec::new())};}
 pub(crate) struct Case(usize);
 pub(crate) fn case(count:usize)->Case{let law:serde_json::Value=serde_json::from_str(include_str!("🎟️wallet/📐️.json")).unwrap();let large=law["largeCounts"].as_array().unwrap().iter().any(|n|n.as_u64()==Some(count as u64));let p=&law[if large{"large"}else{"small"}];let bank=Bank{remaining:RetainedCloneGrant{maximum_items:p["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:p["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:p["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:p["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:p["maximumDepth"].as_u64().unwrap()as usize},fuel:p["fuel"].as_u64().unwrap()};BANKS.with(|s|{let mut s=s.borrow_mut();let index=s.len();s.push(bank);Case(index)})}
 impl Drop for Case{fn drop(&mut self){BANKS.with(|s|{let mut s=s.borrow_mut();assert_eq!(s.len(),self.0+1,"persistent test case bank loans must close in order");s.pop();});}}
 pub(crate) fn remaining()->RetainedCloneGrant{BANKS.with(|s|s.borrow().last().expect("actual persistent case requires its explicit finite bank").remaining)}
 pub(crate) fn available()->RetainedCloneGrant{let p=remaining();RetainedCloneGrant{maximum_items:p.maximum_items.min(1),..p}}
 pub(crate) fn cap(g:RetainedCloneGrant)->RetainedCloneGrant{let p=remaining();RetainedCloneGrant{maximum_items:g.maximum_items.min(p.maximum_items),maximum_copy_bytes:g.maximum_copy_bytes.min(p.maximum_copy_bytes),maximum_capacity_bytes:g.maximum_capacity_bytes.min(p.maximum_capacity_bytes),maximum_release_bytes:g.maximum_release_bytes.min(p.maximum_release_bytes),maximum_depth:g.maximum_depth.min(p.maximum_depth)}}
 pub(crate) fn grant(d:RetirementDemand)->RetainedCloneGrant{let p=remaining();assert!(p.maximum_items>0&&p.maximum_copy_bytes>=d.copy_bytes&&p.maximum_capacity_bytes>=d.capacity_bytes&&p.maximum_release_bytes>=d.release_bytes&&p.maximum_depth>=d.depth,"finite persistent case bank cannot fund actual demand: remaining={p:?},demand={d:?}");RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
 pub(crate) use super::reply::{poll,run,take,begin,read,admit_source,Driver};
 pub(crate) fn admit_progress<T:RetireOwned+Sync+'static>(value:T)->(crate::retained_clone::RetainedCloneSource<T>,RetainedCloneProgress){let(source,p,work)=admit_source(value,RetainedCloneGrant{maximum_items:1<<16,maximum_copy_bytes:1<<24,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24,maximum_depth:4096},1<<20);paid(crate::RetainedWorkOutcome{result:Ok::<_,ValueError>(p),work});(source,p)}
 pub(crate) fn admit<T:RetireOwned+Sync+'static>(value:T)->crate::retained_clone::RetainedCloneSource<T>{admit_progress(value).0}
 pub(crate) fn begin_close(d:RetirementDemand,op:impl FnOnce(&mut crate::RetainedAllocationEffect<'_>)->RetainedWorkOutcome){paid(begin(grant(d),op)).result.unwrap();}
 pub(crate) trait Receipt{fn physical(&self)->RetainedCloneProgress;}
 impl Receipt for RetainedCloneProgress{fn physical(&self)->RetainedCloneProgress{*self}}
 impl Receipt for RetainedCloneStep{fn physical(&self)->RetainedCloneProgress{self.progress()}}
 impl<T> Receipt for(T,RetainedCloneProgress){fn physical(&self)->RetainedCloneProgress{self.1}}
 impl<T:Receipt> Receipt for Option<T>{fn physical(&self)->RetainedCloneProgress{self.as_ref().map_or(Default::default(),Receipt::physical)}}
 impl<T:RetireOwned+Send+Sync+'static> Receipt for super::super::PersistentListReadStep<'_,T>{fn physical(&self)->RetainedCloneProgress{self.progress()}}
 pub(crate) trait Refusal{fn physical(&self)->RetainedCloneProgress;}
 impl Refusal for crate::OriginalRetirementFailure{fn physical(&self)->RetainedCloneProgress{self.retained_progress()}}
  impl Refusal for ValueError{fn physical(&self)->RetainedCloneProgress{self.retained_progress()}}
 impl<T> Refusal for(ValueError,T){fn physical(&self)->RetainedCloneProgress{self.0.retained_progress()}}
 impl<T,O> Refusal for(ValueError,T,O){fn physical(&self)->RetainedCloneProgress{self.0.retained_progress()}}
 pub(crate) fn paid<R:Receipt,E:Refusal>(turn:RetainedWorkOutcome<R,E>)->RetainedWorkOutcome<R,E>{let p=match &turn.result{Ok(r)=>r.physical(),Err(e)=>e.physical()};BANKS.with(|s|{let mut s=s.borrow_mut();let bank=s.last_mut().expect("actual persistent work requires its original finite bank");assert!(p.fits(bank.remaining),"actual persistent receipt exceeds original bank");bank.fuel=bank.fuel.checked_sub(u64::try_from(turn.work).unwrap()).expect("actual persistent CPU exhausted original case fuel");bank.remaining.maximum_items-=p.copied_items;bank.remaining.maximum_copy_bytes-=p.copied_bytes;bank.remaining.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.remaining.maximum_release_bytes-=p.released_bytes;});turn}
 pub(crate) fn take_immutable<S:crate::retained_clone::RetainedClone+crate::snapshot_projection::ImmutableRootProjection>(cursor:&mut crate::immutable_clone::ImmutableRootCloneCursor<S>)->Option<S>{use crate::retained_clone::RetainedCloneCursor;if !cursor.output_ready(){return None}let g=grant(cursor.take_demand().unwrap());let mut output=None;let mut slot=None;let work=std::cell::Cell::new(0u128);let called=crate::effect::run(g,|effect|{let reply=semio_framework_value_control_contract::OriginalEffectReply::borrow(&mut slot)?;let called=cursor.take(&mut output,effect,reply).map(|_|());work.set(effect.performed_work());called});let step=called.and_then(|()|slot.take().expect("immutable take stayed pending"));paid(RetainedWorkOutcome{result:step.map(|step|output.map(|value|(value,step.progress()))),work:work.get()}).result.unwrap().map(|(value,_)|value)}
 pub(crate) fn controlled<T:RetireOwned>(owner:&mut ControlledRetirement<T>,grant:RetainedCloneGrant)->RetainedWorkOutcome{let turn=crate::effect::settle(grant,|effect|poll(effect,|effect,reply|owner.step_into(effect.grant().maximum_copy_bytes,effect,reply)));paid(RetainedWorkOutcome{result:turn.result.map_err(|failure|failure.into_value_error()),work:turn.work})}
}

#[test]fn actual_persistent_producer_take_owns_its_work_with_zero_copy_and_no_denied_or_cached_effect(){let _bank=wallet::case(1);let law:serde_json::Value=serde_json::from_str(include_str!("📤️take/📐️.json")).unwrap();let mut base=original(list(1));let mut authored=original(row(law["authored"].as_i64().unwrap()));macro_rules! take{($producer:expr,$d:expr,$name:literal)=>{{let d=$d;let denied=wallet::paid(wallet::take(wallet::cap(RetainedCloneGrant{maximum_items:0,..grant(d)}),|output,effect,reply|$producer.take_into(output,effect,reply)));assert_eq!(denied.work,u128::from(law["deniedWork"].as_u64().unwrap()));assert!(denied.result.unwrap().is_none());let(turn,heap)=observe(||wallet::paid(wallet::take(grant(d),|output,effect,reply|$producer.take_into(output,effect,reply))));assert_eq!(turn.work,u128::from(law["handoffWork"].as_u64().unwrap()));let(output,p)=turn.result.unwrap().unwrap();assert_eq!(heap,(0,0));assert_eq!(p.copied_bytes,d.copy_bytes);assert_eq!(serde_json::to_value(output.iter().copied().collect::<Vec<_>>()).unwrap(),law["expected"][$name]);assert_eq!(wallet::take(Default::default(),|output,effect,reply|$producer.take_into(output,effect,reply)).work,u128::from(law["cachedWork"].as_u64().unwrap()));let mut output=original(output);close_source(&mut output);}};}
 let mut builder=PersistentListBuilder::<i64>::new(0);let g=grant(builder.finish_demand().unwrap());wallet::paid(wallet::run(g,|effect,reply|builder.finish_into(effect,reply))).result.unwrap();for _ in 0..1000{if builder.output_ready(){break}let g=grant(builder.demand().unwrap());wallet::paid(wallet::run(g,|effect,reply|builder.advance_into(effect,reply))).result.unwrap();}assert!(builder.output_ready());take!(builder,builder.take_demand().unwrap(),"builder");wallet::begin_close(builder.begin_close_demand(),|effect|builder.begin_close_paid(effect));for _ in 0..10000{if builder.terminal_is_empty(){break}let g=grant(builder.close_demand(4096).unwrap());wallet::paid(crate::effect::settle(g,|effect|wallet::poll(effect,|effect,reply|builder.close_into(effect.grant().maximum_copy_bytes,effect,reply)))).result.unwrap();}assert!(builder.terminal_is_empty());
 let mut set=PersistentSet::new(0);for _ in 0..1000{if set.output_ready(){break}let g=grant(set.demand(base.borrow(),authored.borrow()).unwrap());wallet::paid(crate::effect::settle(g,|effect|wallet::poll(effect,|effect,reply|set.advance_into(base.borrow(),authored.borrow(),effect,reply)))).result.unwrap();}assert!(set.output_ready());take!(set,set.take_demand().unwrap(),"set");close(&mut set);
 let mut splice=super::splice::PersistentSplice::new(super::splice::PersistentSpliceKind::Insert,0);for _ in 0..1000{if splice.output_ready(){break}let g=grant(splice.demand(base.borrow(),Some(authored.borrow())).unwrap());wallet::paid(crate::effect::settle(g,|effect|wallet::poll(effect,|effect,reply|splice.advance_into(base.borrow(),Some(authored.borrow()),effect,reply)))).result.unwrap();}assert!(splice.output_ready());take!(splice,splice.take_demand(),"splice");wallet::begin_close(splice.begin_close_demand(),|effect|splice.begin_close_paid(effect));for _ in 0..10000{if splice.terminal_is_empty(){break}let g=grant(splice.close_demand(4096).unwrap());wallet::paid(crate::effect::settle(g,|effect|wallet::poll(effect,|effect,reply|splice.close_into(effect.grant().maximum_copy_bytes,effect,reply)))).result.unwrap();}assert!(splice.terminal_is_empty());close_source(&mut authored);close_source(&mut base);}
